import Component from 'flarum/common/Component';
export default class StatsCards extends Component {
  view() {
    const stats = this.attrs.stats || {
      total: 0,
      positive: 0,
      neutral: 0,
      negative: 0
    };
    return m("div", {
      className: "TraderFeedbackStats"
    }, this.card({
      icon: 'fas fa-exchange-alt',
      value: stats.total,
      label: 'Total Feedbacks',
      type: 'total'
    }), this.card({
      icon: 'fas fa-thumbs-up',
      value: stats.positive,
      label: 'Positive',
      percentage: stats.total > 0 ? Math.round(stats.positive / stats.total * 100) : 0,
      type: 'positive'
    }), this.card({
      icon: 'fas fa-minus-circle',
      value: stats.neutral,
      label: 'Neutral',
      percentage: stats.total > 0 ? Math.round(stats.neutral / stats.total * 100) : 0,
      type: 'neutral'
    }), this.card({
      icon: 'fas fa-thumbs-down',
      value: stats.negative,
      label: 'Negative',
      percentage: stats.total > 0 ? Math.round(stats.negative / stats.total * 100) : 0,
      type: 'negative'
    }));
  }
  card(data) {
    return m("div", {
      className: 'StatsCard StatsCard--' + data.type
    }, m("div", {
      className: "StatsCard-icon"
    }, m("i", {
      className: data.icon
    })), m("div", {
      className: "StatsCard-content"
    }, m("div", {
      className: "StatsCard-value"
    }, data.value), m("div", {
      className: "StatsCard-label"
    }, data.label), data.percentage !== undefined && m("div", {
      className: "StatsCard-percentage"
    }, data.percentage, "%")));
  }
}
flarum.reg.add('huseyinfiliz-traderfeedback', 'admin/components/StatsCards', StatsCards);